package com.pcguard.config;
import com.pcguard.security.AgentApiKeyFilter; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity h,AgentApiKeyFilter agent)throws Exception{return h.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/api/v1/**").permitAll().anyRequest().denyAll()).addFilterBefore(agent,UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource cors(@Value("${pcguard.cors.frontend-url}") String origin){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(java.util.List.of(origin,"http://localhost:5173","http://localhost:5174","http://127.0.0.1:5173","http://127.0.0.1:5174"));c.addAllowedMethod("*");c.addAllowedHeader("*");c.addExposedHeader("Content-Type");c.setMaxAge(3600L);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
